insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-firing-waits-for-sign-off-then-takes-queue-s685','decision','The 12:12Z firing waited for S684''s sign-off, then took the queue','S685 conductor: the firing stood down at 12:17Z while S684 worked (its declaration #3545 had a 12:13Z commit), was told to keep going at 12:18Z by a message in the session, wrote nothing until S684''s sign-off push at 12:47Z, and declared with draft #3551 at 12:52Z. q-wait-for-a-routine-firings-checkpoint-s681 met in practice: the conductor''s call, not a ruling of Sam''s.',array['conductor','routine','coordination'],'proposed','#3551; docs/session_686_handoff.md','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('d-slo-helper-census-fix-in-conductor-run-s685','decision','The outline helper''s census fix shipped inside a conductor run','S685 conductor: scripts/next_slo_colleges.py read only the newest census file, so a 6-row recheck from #3538 (merged in #3544) hid the 118-row census and the outline queue read empty. The fix (#3552, main 7b65b464) repairs collection tooling, so it ran in a collection-only run: each college takes its row from the newest census that holds one.',array['course-outcomes','slo','conductor'],'proposed','#3552','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('d-keep-better-ship-verified-43-s685','decision','Keep-the-better''s generic-heading fix shipped on its 43 verified flips','S685 conductor: after two review rounds #3553 merged (95f85b1e) on the part the replay of 412 decisions verified: 43 flips to kept or new, none the other way. The open finding (a stripped award ending never compared with the program''s award, Redwoods 01821) went to COBIx in writing and became #3557; posts at new colleges leave out rows kept on address evidence with an award ending until it lands.',array['program-requirements','reread','keep-the-better'],'proposed','#3553; #3557','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('d-rule-d-next-session-s685','decision','Rule D and the discontinued capture deferred to the next session','S685 conductor: rule D through rule_d at City College of San Francisco, Santa Rosa Junior and College of the Desert, and kb/_program_discontinued.py --capture, did not run. A rule D read is a second pass at a college the S683 wave posted, and the second-pass dispatch fix (#3558) was still in CI. First for the next session once #3558 lands.',array['program-requirements','rule-d','conductor'],'proposed','docs/session_686_handoff.md','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('d-display-confirmed-by-live-count-s685','decision','Display build 3e8088e082eb confirmed by a closing live count','S685 conductor: the whole display build (run 44535255196) sent all 18,238 writes and its confirming read answered HTTP 500, so the runner''s record says unconfirmed. A closing live count through migrate run 44536820147 found 18,323 rows at 3e8088e082eb, 15 and 16 at two older builds, none without a display or build key: confirmed. The record stays as the runner wrote it.',array['program-requirements','display','conductor'],'proposed','#3556; migrate run 44536820147','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('d-reads-stop-is-forty-dollars-s685','decision','A reread''s stop is $40 per college per run, not the plan''s ceiling','S685 conductor: the reread plan''s per-college ceilings price only the aim rows, so a paid read can pass them honestly (American River''s preview priced 143 programs at $11.65). The stop is Sam''s $40 per college per run on the estimate; the ceiling orders the work and never halts it.',array['program-requirements','reread','cost'],'proposed','kb/program_requirements_reread_plan_s683.json','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('d-live-reads-through-migrate-runner-s685','decision','Live reads went through the migrate runner when the SQL prompt had no one to answer it','S685 conductor: one read through the SQL tool passed at 12:22Z; at 13:25Z a worker''s call waited on the per-call prompt with nobody to answer it, and the worker was stopped. Every later live read (the display gate, the closing count, the second pass''s live read) went through supabase-migrate.yml with a committed receipt.',array['conductor','supabase','reads'],'proposed','kb/receipts/migration_s685_display_gate_read_44534279276.json','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('p-apply-before-thread-read-s685','pitfall','A PR''s file was applied before its thread was read','S685: the conductor applied S684''s 22 memory rows (run 44528020042) before reading #3545''s thread, where COBIx had twice asked for a staff contact detail to come out of one row first. It was live about three minutes; a guarded update removed it (run 44528997886) and the file was fixed on #3545 before it merged. Read a PR''s thread before applying any file it carries.',array['conductor','memory','privacy'],'proposed','#3545; kb/migrations/2026-11-19_s685_cpl_memory_email_scrub.sql','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('p-second-pass-run-never-named-s685','pitfall','A second pass named no run: the receipt rule dropped every posted run','S685: keep-the-better''s posted_runs dropped a run from dispatch whenever a reread receipt for it was on the branch. The 43 flips are records of runs posted once in S683 or S684, so 42 would never be named; the second pass stopped itself in its dry run. #3558: with live_runs supplied, a run is named when a kept or new record is not live at that run.',array['program-requirements','reread','keep-the-better'],'proposed','#3558','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('p-helper-reads-only-newest-file-s685','pitfall','The outline helper read only the newest census file','S685: next_slo_colleges.census() read only the newest file in kb/course_outline_census/. A 6-row recheck added on 2026-11-19 hid the 118-row census: 75 colleges skipped for want of a census row and --next said the queue was empty. A reader of dated snapshot files takes each key from the newest file that holds it (#3552).',array['course-outcomes','slo','census'],'proposed','#3552','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('p-cobix-watch-missed-three-s685','pitfall','The COBIx watcher missed three comments; the thread read caught them','S685: the watcher missed COBIx''s comments on #3556 (13:57Z), #3557 (14:07Z, two) and #3558 (14:08Z); pr-gate''s thread read before each merge caught them. Second night running (p-cobix-watch-misses-on-search-lag-s684). The thread read before a merge is the gate; the watcher is a convenience.',array['conductor','cobix','merge'],'proposed','#3556; #3557; #3558','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('f-generic-heading-cost-43-rereads-s685','fact','A generic CourseLeaf heading had set aside 43 good re-reads','S685: replaying keep-the-better over the 412 committed decisions with #3553''s page_is_own test flipped 43 to kept or new: Evergreen Valley 13, Citrus 6, Compton 6, Los Angeles Pierce 5, Ventura 3, San Bernardino Valley 3, CCSF 2, and East Los Angeles, El Camino, Moorpark, Porterville and West Los Angeles 1 each. None flipped the other way. The second pass re-posts them.',array['program-requirements','reread','keep-the-better'],'proposed','#3553','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('f-display-confirm-read-unpaged-s685','fact','The display apply''s confirming read is unpaged','S685 (COBIx on #3556): the one-college run with 85 keys confirmed; the whole build with 18,238 keys answered HTTP 500 after every write had gone out. The confirming read is a single unpaged read, so every full-build run will fail the same way until it is paged as the write side is. A plain session''s code change.',array['program-requirements','display'],'proposed','#3556','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('f-outline-readers-need-header-fixes-s685','fact','Three outline indexes ran and none could load','S685: Feather River read 337 pages, but 336 of its 2,072 SLOs are the Learning Outcomes table header (standing test 24 of 26). Palomar''s trial filed the objectives section and table headers as SLOs. San Diego College of Continuing Education indexed 0 of 242 (no NewSearch request, as Rio Hondo). Each needs a reader change; no rows loaded.',array['course-outcomes','slo','readers'],'proposed','claude/slo-feather_river; claude/slo-palomar','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('m-display-build-live-s685','milestone','Display build 3e8088e082eb live for CPL Pathways and Sierra','S685: display build 3e8088e082eb (18,323 statements, 830 changed from 545de21a6edc) carries Lassen''s five, #3497''s and #3508''s writes, both reread waves and #3548. One-college run 44531512075, gate read 44534279276, whole build 44535255196, closing count 44536820147. The page file''s build stamp merged in #3556 (648ee2cb).',array['program-requirements','display'],'proposed','#3556','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('m-gap-census-5203-s685','milestone','The harvest gap census: 5,203 programs left','S685: harvest-gap-census.yml on main 58b50c45 (run 44531283594): universe 20,282, passing 14,986, 5,203 left against 5,395 on 2026-11-18 (192 fewer); collected with gaps 93.',array['program-requirements','census'],'proposed','run 44531283594','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19'),
('m-keep-better-and-helper-merged-s685','milestone','Keep-the-better''s generic-heading fix and the outline helper fix merged','S685: #3553 (main 95f85b1e) lets a generic heading pass the own-program test only where the committed files show the page is the program''s own, and keeps a live run equal to this run as posted; #3552 (7b65b464) restores the outline queue. Open: #3557 (award ending, award_tail) and #3558 (second-pass dispatch naming).',array['program-requirements','course-outcomes','keep-the-better'],'proposed','#3552; #3553','SkyTowhee (S685), the conductor',null,'SkyTowhee (S685)',date '2026-11-19')
